    for (int i = 0; i < num_lines; i++) {
        fprintf(fp, "%s
", lines[i]);
    }
    fclose(fp);
    return filename;
}

// Deletes a temporary test file created by helper_create_test_file.
void helper_cleanup_test_file(char *filename) {
    remove(filename);
    free(filename);
}


